private void Rap_FormatShitjeAlpetrolA5_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            this.Detail.Controls.Add(CreateXRTable());
            System.Data.DataTable dt = ((System.Data.DataSet)(this.DataSource)).Tables[0];
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                //object NR = dt.Rows[i]["calculatedField1"];
                object nrArt = dt.Rows[i]["KODI"];
                object PERSHKRIMI = dt.Rows[i]["PERSHKRIMI"];
                object NJESI = dt.Rows[i]["PERSHKRIMNJESIA"];
                object SASIA = dt.Rows[i]["SASIA"];
                object CMIMIMETVSH = Convert.ToDouble(Convert.ToDouble(dt.Rows[i]["CMIMIPATVSH"]) * (1 + Convert.ToDouble(dt.Rows[i]["TVSH"])));
                object CMIMIPATVSH = dt.Rows[i]["CMIMIPATVSH"];
                object VLEFTAPATVSH = dt.Rows[i]["VLEFTAPATVSH"];
                object tvsh = Convert.ToDouble(dt.Rows[i]["TVSH"]) * Convert.ToDouble(dt.Rows[i]["VLEFTAPATVSH"]);   // Round( [TVSH] * [VLEFTAPATVSH],2)
                object VLEFTAMETVSH = dt.Rows[i]["VLEFTAMETVSH"];

                object[] obj = new object[10];
                obj[0] = (i + 1).ToString();
                obj[1] = nrArt;
                obj[2] = PERSHKRIMI;
                obj[3] = NJESI;
                obj[4] = SASIA;
                obj[5] = CMIMIMETVSH;
                obj[6] = CMIMIPATVSH;
                obj[7] = VLEFTAPATVSH;
                obj[8] = tvsh;
                obj[9] = VLEFTAMETVSH;
                trupi.Add(obj);
            }
}

