private void xrLabel1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (GetCurrentColumnValue("PERSHKRIMNIVELI").ToString() == "Fature shitje")
                xrLabel1.Text = "FATURUAR NGA PIKA";
            else if (GetCurrentColumnValue("PERSHKRIMNIVELI").ToString() == "Urdher shitje")
                xrLabel1.Text = "FURNIZUAR NGA PIKA";
}

